{
  description = "Nix flake for a MacBook and the ai-dev Linux home";
  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixpkgs-unstable";
    darwin.url = "github:nix-darwin/nix-darwin/master";
    darwin.inputs.nixpkgs.follows = "nixpkgs";
    home-manager.url = "github:nix-community/home-manager";
    home-manager.inputs.nixpkgs.follows = "nixpkgs";
    hunk.url = "github:modem-dev/hunk";
  };

  outputs = {
    nixpkgs,
    darwin,
    home-manager,
    hunk,
    ...
  }: let
    systems = [
      "aarch64-darwin"
      "x86_64-linux"
    ];
    forAllSystems = nixpkgs.lib.genAttrs systems;
    packagesFor = system:
      import nixpkgs {
        inherit system;
        config.allowUnfree = true;
      };
    darwinConfig = darwin.lib.darwinSystem {
      specialArgs = {inherit hunk;};
      modules = [
        home-manager.darwinModules.home-manager
        ./configuration.nix
      ];
    };
    aiDev = home-manager.lib.homeManagerConfiguration {
      pkgs = packagesFor "x86_64-linux";
      extraSpecialArgs = {
        inherit hunk;
        repoRoot = "/home/michael/dev/nix-config";
      };
      modules = [
        ./home.nix
        ./hosts/ai-dev.nix
      ];
    };
  in {
    formatter = forAllSystems (system: let
      pkgs = packagesFor system;
    in
      pkgs.writeShellApplication {
        name = "nix-config-fmt";
        runtimeInputs = [pkgs.alejandra];
        text = ''
          exec alejandra "''${@:-.}"
        '';
      });

    darwinConfigurations.macbook = darwinConfig;
    homeConfigurations."michael@ai-dev" = aiDev;

    checks.aarch64-darwin = {
      macbook-system = darwinConfig.config.system.build.toplevel;
      macbook-home = darwinConfig.config.home-manager.users.mm.home.activationPackage;
      hunk = hunk.packages.aarch64-darwin.hunk;
      opencode = (packagesFor "aarch64-darwin").opencode;
    };
    checks.x86_64-linux = {
      ai-dev-home = aiDev.activationPackage;
      ai-dev-profile-command = (packagesFor "x86_64-linux").runCommand "ai-dev-profile-command" {} ''
        if grep -q "profile install" ${aiDev.activationPackage}/activate; then
          echo "ai-dev activation uses deprecated nix profile install" >&2
          exit 1
        fi
        touch "$out"
      '';
      hunk = hunk.packages.x86_64-linux.hunk;
      opencode = (packagesFor "x86_64-linux").opencode;
    };
  };
}

{
  config,
  lib,
  ...
}: {
  imports = [./ai-dev-runtime.nix];

  home = {
    username = "michael";
    homeDirectory = "/home/michael";

    # /tmp is a quota-limited RAM tmpfs; agent scratch belongs on disk.
    sessionVariables.TMPDIR = "/var/tmp/michael";

    # ai-dev is headless: pi-mcp-adapter has no browser or display to open
    # MCP UI sessions in, so keep tool results inline only. Hosts with a
    # browser keep the default viewer behaviour.
    sessionVariables.MCP_UI_VIEWER = "none";
  };

  # Home Manager still uses the deprecated `nix profile install` alias.
  home.activation.installPackages = lib.mkForce (lib.hm.dag.entryAfter ["writeBoundary"] ''
    aiDevNix="$(command -v nix)"
    nixProfileRemove 'home-manager-path'
    run "$aiDevNix" profile add ${config.home.path}
    unset aiDevNix
  '');

  news.display = "silent";

  programs.fish.interactiveShellInit = lib.mkBefore ''
    fish_add_path --prepend "$HOME/.nix-profile/bin"
  '';

  programs.starship.settings = {
    hostname.disabled = true;
    username.disabled = true;
  };

  programs.git.includes = [
    {
      path = "~/.gitconfig-personal";
    }
  ];
}

{...}: {
  xdg.configFile."fish/conf.d/coding-agent-aliases.fish" = {
    force = true;
    text = ''
      function codex --wraps=codex --description "alias codex codex --dangerously-bypass-approvals-and-sandbox"
          command codex --dangerously-bypass-approvals-and-sandbox $argv
      end

      function claude --wraps=claude --description "alias claude claude --dangerously-skip-permissions"
          command claude --dangerously-skip-permissions $argv
      end
    '';
  };

  systemd.user.services.moshi-hook = {
    Unit = {
      Description = "Moshi agent hooks and loopback gateway";
      Wants = ["network-online.target"];
      After = ["network-online.target"];
    };
    Service = {
      Type = "simple";
      ExecStart = "%h/.local/bin/moshi-hook serve";
      Restart = "on-failure";
      RestartSec = 5;
    };
    Install.WantedBy = ["default.target"];
  };

  # Weekly store garbage collection. Determinate Nix owns the binary, so call it
  # by its profile path rather than pulling a second nix into the closure.
  systemd.user.services.nix-gc = {
    Unit.Description = "Nix garbage collection";
    Service = {
      Type = "oneshot";
      ExecStart = "/nix/var/nix/profiles/default/bin/nix-collect-garbage --delete-older-than 30d";
    };
  };

  systemd.user.timers.nix-gc = {
    Unit.Description = "Weekly Nix garbage collection";
    Timer = {
      OnCalendar = "weekly";
      Persistent = true;
      RandomizedDelaySec = "1h";
    };
    Install.WantedBy = ["timers.target"];
  };
}

{
  config,
  lib,
  ...
}: {
  imports = [
    ./home
  ];

  home = {
    stateVersion = "22.05";
    sessionPath = ["${config.home.homeDirectory}/.local/bin"];

    shellAliases = {
      ls = "eza -la";
      cat = "bat";
    };

    sessionVariables = {
      EDITOR = "nvim";
      VISUAL = "nvim";
      LESS = "--chop-long-lines --HILITE-UNREAD --ignore-case --incsearch --jump-target=4 --LONG-PROMPT --no-init --quit-if-one-screen --RAW-CONTROL-CHARS --use-color --window=4";
    };

    file.".hushlogin".text = "";

    # Home Manager master and nixpkgs-unstable can advertise different
    # development release labels despite being their documented pairing.
    enableNixpkgsReleaseCheck = lib.mkDefault false;
  };

  manual.manpages.enable = false;
  programs.home-manager.enable = true;
}

variable "docker_host_ssh_public_key" {
  type        = string
  description = "SSH public key for the ansible user on the docker-host VM."
  default     = "ssh-ed25519 REDACTED"
}

variable "proxmox_host" {
  type        = string
  description = "Proxmox API and SSH host; defaults to its Tailscale MagicDNS name."
  default     = "proxmox"
}

variable "unifi_ssh_public_key" {
  type        = string
  description = "SSH public key for the mm user on the UniFi OS Server VM."
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJB/REDACTED"
}

variable "ai_dev_ssh_public_key" {
  type        = string
  description = "SSH public key for the michael user on the ai-dev VM (the laptop key)."
  default     = "ssh-ed25519 REDACTED"
}

variable "truenas_macaddr" {
  type        = string
  description = "Pinned TrueNAS VM NIC MAC address. Provide via TF_VAR_truenas_macaddr in the ignored root .envrc."
  sensitive   = true
}

variable "docker_host_macaddr" {
  type        = string
  description = "Pinned docker-host VM NIC MAC address. Provide via TF_VAR_docker_host_macaddr in the ignored root .envrc."
  sensitive   = true
}

variable "ubuntu_server_24_04_template_vmid" {
  type        = number
  description = "Proxmox VMID for the ubuntu-server-24-04 cloud-init template."
  default     = 9003
}

variable "arch_cloud_template_vmid" {
  type        = number
  description = "Proxmox VMID for the arch-cloud cloud-init template."
  default     = 9002
}

